import{c as e,Q as l,j as t,m as r}from"./chunks/framework.BPKcPtvA.js";const h=JSON.parse('{"title":"制作人面对面问答回顾 首屆共创议会名单公开","description":"RO3 先锋测试结束，制作人回应玩家问题，共创议会正式启动","frontmatter":{"title":"制作人面对面问答回顾 首屆共创议会名单公开","description":"RO3 先锋测试结束，制作人回应玩家问题，共创议会正式启动"},"headers":[],"relativePath":"news/producer-qa-202510.md","filePath":"news/producer-qa-202510.md","lastUpdated":1779114110000}'),i={name:"news/producer-qa-202510.md"};function o(n,a,s,d,p,c){return l(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="制作人面对面问答回顾" tabindex="-1">制作人面对面问答回顾 <a class="header-anchor" href="#制作人面对面问答回顾" aria-label="Permalink to &quot;制作人面对面问答回顾&quot;">​</a></h1><p>日期：2025-10-03</p><p>RO3「先锋测试」已结束，官方公开「制作人面对面」问答回顾，同时正式启动「共创议会」并公开首屆议员名单。</p><h2 id="制作人面对面" tabindex="-1">制作人面对面 <a class="header-anchor" href="#制作人面对面" aria-label="Permalink to &quot;制作人面对面&quot;">​</a></h2><p>制作人 YU 在本次活动中首度公开多项核心设计方向：</p><ul><li><strong>十人副本</strong>设计方向首次揭露</li><li><strong>公会联赛</strong>玩法规划</li><li>承诺持续优化操作流畅度</li><li>强调「与玩家共同成长」的开发理念</li></ul><h2 id="共创议会正式启动" tabindex="-1">共创议会正式启动 <a class="header-anchor" href="#共创议会正式启动" aria-label="Permalink to &quot;共创议会正式启动&quot;">​</a></h2><p>为落实「与玩家共同开发」理念，官方宣布共创议会正式启动，首屆 4 位代表繁体中文社群的成员名单如下：</p><ul><li>由玩家投票选出</li><li>皆拥有十年以上 RO 及其他 MMORPG 经验</li><li>将定期参加茶话会并直接向开发团队提供意见</li><li>未来游戏上市后，共创玩家的贡献将展示在游戏内「荣誉大街」</li></ul><h2 id="后续规划" tabindex="-1">后续规划 <a class="header-anchor" href="#后续规划" aria-label="Permalink to &quot;后续规划&quot;">​</a></h2><ul><li>2025 年 10 月 25 日举办 GVG 攻城战线下抢鲜体验赛</li><li>游戏预计 2026 年全球同步上线</li></ul><p><small>消息来源：巴哈姆特 GNN 整理报导</small></p>',12)])])}const _=e(i,[["render",o]]);export{h as __pageData,_ as default};
